23|// Feature-detect `Iterator.from` (added in ES2025) without augmenting the
24|// global scope. Declaring `var Iterator` in a `declare global` block leaks a
25|// conflicting global variable into the bundled `.d.ts` (TS2403 when compiled
26|// against the ESNext lib). We cast via `globalThis` to satisfy the type checker
27|// while keeping the runtime feature detect accurate. (#1273)
28|const _globalIterator = (globalThis as any).Iterator as
29|	| undefined
30|	| { from: <T>(iterable: Iterator<T>) => IterableIterator<T> }
31|const hasIteratorFrom =
32|	typeof _globalIterator?.from === "function"
