34|export function enableMapSet() {
35|	class DraftMap extends Map {
36|		[DRAFT_STATE]: MapState
37|
38|		constructor(target: AnyMap, parent?: ImmerState) {
39|			super()
40|			this[DRAFT_STATE] = {
41|				type_: ArchType.Map,
42|				parent_: parent,
43|				scope_: parent ? parent.scope_ : getCurrentScope()!,
44|				modified_: false,
45|				finalized_: false,
46|				copy_: undefined,
47|				assigned_: undefined,
48|				base_: target,
49|				draft_: this as any,
50|				isManual_: false,
51|				revoked_: false,
52|				callbacks_: []
53|			}
54|		}
55|
56|		get size(): number {
57|			return latest(this[DRAFT_STATE]).size
58|		}
59|
60|		has(key: any): boolean {
61|			return latest(this[DRAFT_STATE]).has(key)
62|		}
63|
64|		set(key: any, value: any) {
65|			const state: MapState = this[DRAFT_STATE]
66|			assertUnrevoked(state)
67|			if (!latest(state).has(key) || latest(state).get(key) !== value) {
68|				prepareMapCopy(state)
69|				markChanged(state)
70|				state.assigned_!.set(key, true)
71|				state.copy_!.set(key, value)
72|				state.assigned_!.set(key, true)
73|				handleCrossReference(state, key, value)
74|			}
75|			return this
76|		}
77|
78|		delete(key: any): boolean {
79|			if (!this.has(key)) {
80|				return false
81|			}
82|
83|			const state: MapState = this[DRAFT_STATE]
84|			assertUnrevoked(state)
85|			prepareMapCopy(state)
86|			markChanged(state)
87|			if (state.base_.has(key)) {
88|				state.assigned_!.set(key, false)
89|			} else {
90|				state.assigned_!.delete(key)
91|			}
92|			state.copy_!.delete(key)
93|			return true
94|		}
95|
96|		clear() {
97|			const state: MapState = this[DRAFT_STATE]
98|			assertUnrevoked(state)
99|			if (latest(state).size) {
100|				prepareMapCopy(state)
101|				markChanged(state)
102|				state.assigned_ = new Map()
103|				each(state.base_, key => {
104|					state.assigned_!.set(key, false)
105|				})
106|				state.copy_!.clear()
107|			}
108|		}
109|
110|		forEach(cb: (value: any, key: any, self: any) => void, thisArg?: any) {
111|			const state: MapState = this[DRAFT_STATE]
112|			latest(state).forEach((_value: any, key: any, _map: any) => {
113|				cb.call(thisArg, this.get(key), key, this)
114|			})
115|		}
116|
117|		get(key: any): any {
118|			const state: MapState = this[DRAFT_STATE]
119|			assertUnrevoked(state)
120|			const value = latest(state).get(key)
121|			if (state.finalized_ || !isDraftable(value)) {
122|				return value
123|			}
124|			if (value !== state.base_.get(key)) {
125|				return value // either already drafted or reassigned
126|			}
127|			// despite what it looks, this creates a draft only once, see above condition
128|			const draft = createProxy(state.scope_, value, state, key)
129|			prepareMapCopy(state)
130|			state.copy_!.set(key, draft)
131|			return draft
132|		}
133|
134|		keys(): IterableIterator<any> {
135|			return latest(this[DRAFT_STATE]).keys()
136|		}
137|
138|		values(): IterableIterator<any> {
139|			const iterator = this.keys()
140|			return iteratorFrom({
141|				next: () => {
142|					const r = iterator.next()
143|					/* istanbul ignore next */
144|					if (r.done) return r
145|					const value = this.get(r.value)
146|					return {
147|						done: false,
148|						value
149|					}
150|				}
151|			})
152|		}
153|
154|		entries(): IterableIterator<[any, any]> {
155|			const iterator = this.keys()
156|			return iteratorFrom({
157|				next: () => {
158|					const r = iterator.next()
159|					/* istanbul ignore next */
160|					if (r.done) return r
161|					const value = this.get(r.value)
162|					return {
163|						done: false,
164|						value: [r.value, value]
165|					}
166|				}
167|			})
168|		}
169|
170|		[Symbol.iterator]() {
171|			return this.entries()
172|		}
173|	}
174|
175|	function iteratorFrom<T, TReturn>(
176|		iterable: Iterator<T, TReturn>
177|	): IterableIterator<T> {
178|		if (hasIteratorFrom) {
179|			return _globalIterator!.from(iterable)
180|		}
181|
182|		const iterator: IterableIterator<T> = {
183|			...iterable,
184|			[Symbol.iterator]: () => iterator
185|		}
186|
187|		return iterator
188|	}
189|
190|	function proxyMap_<T extends AnyMap>(
191|		target: T,
192|		parent?: ImmerState
193|	): [T, MapState] {
194|		// @ts-ignore
195|		const map = new DraftMap(target, parent)
196|		return [map as any, map[DRAFT_STATE]]
197|	}
198|
199|	function prepareMapCopy(state: MapState) {
200|		if (!state.copy_) {
201|			state.assigned_ = new Map()
202|			state.copy_ = new Map(state.base_)
203|		}
204|	}
205|
206|	class DraftSet extends Set {
207|		[DRAFT_STATE]: SetState
208|		constructor(target: AnySet, parent?: ImmerState) {
209|			super()
210|			this[DRAFT_STATE] = {
211|				type_: ArchType.Set,
212|				parent_: parent,
213|				scope_: parent ? parent.scope_ : getCurrentScope()!,
214|				modified_: false,
215|				finalized_: false,
216|				copy_: undefined,
217|				base_: target,
218|				draft_: this,
219|				drafts_: new Map(),
220|				revoked_: false,
221|				isManual_: false,
222|				assigned_: undefined,
223|				callbacks_: []
224|			}
225|		}
226|
227|		get size(): number {
228|			return latest(this[DRAFT_STATE]).size
229|		}
230|
231|		has(value: any): boolean {
232|			const state: SetState = this[DRAFT_STATE]
233|			assertUnrevoked(state)
234|			// bit of trickery here, to be able to recognize both the value, and the draft of its value
235|			if (!state.copy_) {
236|				return state.base_.has(value)
237|			}
238|			if (state.copy_.has(value)) return true
239|			if (state.drafts_.has(value) && state.copy_.has(state.drafts_.get(value)))
240|				return true
241|			return false
242|		}
243|
244|		add(value: any): any {
245|			const state: SetState = this[DRAFT_STATE]
246|			assertUnrevoked(state)
247|			if (!this.has(value)) {
248|				prepareSetCopy(state)
249|				markChanged(state)
250|				state.copy_!.add(value)
251|				handleCrossReference(state, value, value)
252|			}
253|			return this
254|		}
255|
256|		delete(value: any): any {
257|			if (!this.has(value)) {
258|				return false
259|			}
260|
261|			const state: SetState = this[DRAFT_STATE]
262|			assertUnrevoked(state)
263|			prepareSetCopy(state)
264|			markChanged(state)
265|			return (
266|				state.copy_!.delete(value) ||
267|				(state.drafts_.has(value)
268|					? state.copy_!.delete(state.drafts_.get(value))
269|					: /* istanbul ignore next */ false)
270|			)
271|		}
272|
273|		clear() {
274|			const state: SetState = this[DRAFT_STATE]
275|			assertUnrevoked(state)
276|			if (latest(state).size) {
277|				prepareSetCopy(state)
278|				markChanged(state)
279|				state.copy_!.clear()
280|			}
281|		}
282|
283|		values(): IterableIterator<any> {
284|			const state: SetState = this[DRAFT_STATE]
285|			assertUnrevoked(state)
286|			prepareSetCopy(state)
287|			return state.copy_!.values()
288|		}
289|
290|		entries(): IterableIterator<[any, any]> {
291|			const state: SetState = this[DRAFT_STATE]
292|			assertUnrevoked(state)
293|			prepareSetCopy(state)
294|			return state.copy_!.entries()
295|		}
296|
297|		keys(): IterableIterator<any> {
298|			return this.values()
299|		}
300|
301|		[Symbol.iterator]() {
302|			return this.values()
303|		}
304|
305|		forEach(cb: any, thisArg?: any) {
306|			const iterator = this.values()
307|			let result = iterator.next()
308|			while (!result.done) {
309|				cb.call(thisArg, result.value, result.value, this)
310|				result = iterator.next()
311|			}
312|		}
313|	}
314|	function proxySet_<T extends AnySet>(
315|		target: T,
316|		parent?: ImmerState
317|	): [T, SetState] {
318|		// @ts-ignore
319|		const set = new DraftSet(target, parent)
320|		return [set as any, set[DRAFT_STATE]]
321|	}
322|
323|	function prepareSetCopy(state: SetState) {
324|		if (!state.copy_) {
325|			// create drafts for all entries to preserve insertion order
326|			state.copy_ = new Set()
327|			state.base_.forEach(value => {
328|				if (isDraftable(value)) {
329|					const draft = createProxy(state.scope_, value, state, value)
330|					state.drafts_.set(value, draft)
331|					state.copy_!.add(draft)
332|				} else {
333|					state.copy_!.add(value)
334|				}
335|			})
336|		}
337|	}
338|
339|	function assertUnrevoked(state: any /*ES5State | MapState | SetState*/) {
340|		if (state.revoked_) die(3, JSON.stringify(latest(state)))
341|	}
342|
343|	function fixSetContents(target: ImmerState) {
344|		// For sets we clone before iterating, otherwise we can get in endless loop due to modifying during iteration, see #628
345|		// To preserve insertion order in all cases we then clear the set
346|		if (target.type_ === ArchType.Set && target.copy_) {
347|			const copy = new Set(target.copy_)
348|			target.copy_.clear()
349|			copy.forEach(value => {
350|				target.copy_!.add(getValue(value))
351|			})
352|		}
353|	}
354|
355|	loadPlugin(PluginMapSet, {proxyMap_, proxySet_, fixSetContents})
356|}

